/* From Uiverse.io by Peary74 - Tags: button, cloud, save */
.__UIV_SCOPE__ .btnCloud {
  background-color: transparent;
  position: relative;
  fill: rgb(155, 153, 153);
  border: none;
}

.__UIV_SCOPE__ .btnCloud::after {
  content: 'SAVE';
  position: absolute;
  top: -50%;
  left: 50%;
  transform: translateX(-50%);
  background-color: #fff;
  padding: 3px 9px;
  border-radius: 5px;
  transition: 200ms linear;
  transition-delay: 200ms;
  color: black;
  font-size: 13px;
  visibility: hidden;
}

.__UIV_SCOPE__ .icon {
  transform: scale(1.4);
  transition: 200ms linear;
}

.__UIV_SCOPE__ .btnCloud:hover > .icon {
  transform: scale(1.7);
}

.__UIV_SCOPE__ .btnCloud:hover > .icon path {
  fill: #fff;
  cursor: pointer;
}

.__UIV_SCOPE__ .btnCloud:hover::after {
  visibility: visible;
  opacity: 1;
  top: -100%;
}
